#' CFA vs ESEM
#'
#' Fits the hypothesised correlated-factors model as a CFA and as an 
#' exploratory structural equation model (every item may load on every 
#' factor), and lists each factor correlation as obtained from composite 
#' scores, corrected composites, the CFA, factor scores and the ESEM.
#' 
#'
#' @examples
#' \donttest{
#' data('wizdata', package = 'psyWiz')
#' psyWiz::esemCfa(wizdata, run = TRUE, factors = list(
#'     list(label = 'Trust', vars = c('trust1', 'trust2', 'trust3', 'trust4')),
#'     list(label = 'Stress', vars = c('stress1', 'stress2', 'stress3', 'stress4'))))
#'}
#' @param data the data as a data frame
#' @param factors a list of lists, each with a \code{label} (the factor name)
#'   and \code{vars} (the names of its items)
#' @param run \code{TRUE} or \code{FALSE} (default), fit the models; while
#'   \code{FALSE} only a summary of the plan is shown
#' @param type \code{'auto'} (default; ordinal variables are treated as
#'   ordinal, continuous ones as continuous), \code{'ordinal'} or
#'   \code{'continuous'}
#' @param estimator \code{'auto'} (default; MLR for continuous items, WLSMV
#'   for ordinal items), \code{'ML'}, \code{'MLR'}, \code{'MLM'},
#'   \code{'WLSMV'}, \code{'ULSMV'}, \code{'DWLS'} or \code{'ULS'}
#' @param missing \code{'auto'} (default; FIML for ML and MLR, pairwise
#'   deletion for ordinal items), \code{'listwise'}, \code{'fiml'} or
#'   \code{'pairwise'}
#' @param rotation \code{'target'} (default; cross-loadings are rotated
#'   towards zero) or \code{'geomin'}
#' @param parallel \code{TRUE} (default) or \code{FALSE}, fit the models
#'   concurrently when one takes more than a second
#' @param showLoadings \code{TRUE} (default) or \code{FALSE}, show the
#'   standardized loadings of both models
#' @param showCors \code{TRUE} (default) or \code{FALSE}, show each factor
#'   correlation under the different scoring methods
#' @param highlight \code{TRUE} or \code{FALSE} (default), show cross-loadings
#'   of 0.30 or more and own-factor loadings below 0.40 in red
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$todo} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$fit} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$comparison} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$loadings} \tab \tab \tab \tab \tab a table \cr
#'   \code{results$cors} \tab \tab \tab \tab \tab a table \cr
#' }
#'
#' Tables can be converted to data frames with \code{asDF} or \code{\link{as.data.frame}}. For example:
#'
#' \code{results$fit$asDF}
#'
#' \code{as.data.frame(results$fit)}
#'
#' @export
esemCfa <- function(
    data,
    factors = list(
                list(label="Factor 1", vars=list()),
                list(label="Factor 2", vars=list())),
    run = FALSE,
    type = "auto",
    estimator = "auto",
    missing = "auto",
    rotation = "target",
    parallel = TRUE,
    showLoadings = TRUE,
    showCors = TRUE,
    highlight = FALSE) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("esemCfa requires jmvcore to be installed (restart may be required)")

    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame())


    options <- esemCfaOptions$new(
        factors = factors,
        run = run,
        type = type,
        estimator = estimator,
        missing = missing,
        rotation = rotation,
        parallel = parallel,
        showLoadings = showLoadings,
        showCors = showCors,
        highlight = highlight)

    analysis <- esemCfaClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

